+async fn fc_0_deferred_session() -> (Arc<MemorySession>, Vec<AgentEvent>, Vec<Arc<RequestLog>>) {
+    let b = MockTool::new("b", serde_json::json!({}));
+    let (triage, models) = fc_0_chain(
